// ---------- Cloudflare Workers AI art (made once, stored in R2 forever) ----------
const WEEK0 = Date.UTC(2026, 10, 16);
const weekNo = () => Math.max(1, Math.floor((Date.now() - WEEK0) / (7 * 864e5)) + 1);
const AI_THEME = {
  rooftop: 'the rooftops of a huge modern city, skyscrapers, water towers, antennas and rooftop AC units',
  skate: 'a sunny California beach skatepark with palm trees, concrete bowls and the ocean behind',
  docks: 'an industrial cargo harbor with stacked shipping containers, gantry cranes and cargo ships on calm water',
  frost: 'a snowy mountain ski resort with snow-covered pine forest, jagged peaks and wooden lodges',
  temple: 'ancient jungle temple ruins with mossy stone pyramids, waterfalls and misty rainforest',
};
const AI_TIME = { Day: 'bright midday sun, clear blue sky', Night: 'at night, glowing lights, deep blue night sky with stars', Sunset: 'at sunset, golden hour, orange and purple sky' };
const AI_FABRIC = {
  denim: 'soft washed denim jeans cloth, subtle fine diagonal twill texture with low contrast, slightly faded and worn, uniform light grey color, like a real pair of jeans',
  camo: 'light grey and white camouflage pattern printed on cotton fabric',
};
function aiArtJob(key) {
  let m = key.match(/^bg\/gen\/wk(\d{1,4})_([a-z]+)_([A-Za-z]+)\.jpg$/);
  if (m) { const n = +m[1]; if (n < 1 || n > weekNo() + 1 || !AI_THEME[m[2]] || !AI_TIME[m[3]]) return null;
    return { w: 1792, h: 672, seed: n * 7919, prompt: `Photorealistic ultra-wide panoramic landscape photograph of ${AI_THEME[m[2]]}, ${AI_TIME[m[3]]}. Cinematic, highly detailed, wide open vista, horizon across the middle of the frame, distant background scenery for a video game skybox. No people, no text, no logos, no watermark.` }; }
  if (key === 'bg/complex.jpg') return { w: 1792, h: 672, seed: 4242, prompt: 'Photorealistic ultra-wide panoramic photograph of a futuristic neon city skyline at dusk seen from an industrial rooftop yard, glowing magenta and cyan skyscrapers, pink and orange sunset sky, cinematic, highly detailed, horizon across the middle of the frame, distant background scenery for a video game skybox. No people, no text, no logos, no watermark.' };
  m = key.match(/^skins\/fab_([a-z]+)\.jpg$/);
  if (m && AI_FABRIC[m[1]]) return { w: 1024, h: 1024, seed: 7, prompt: `Photorealistic extreme close-up photograph of ${AI_FABRIC[m[1]]}, the fabric surface fills the entire square frame edge to edge, flat, evenly lit from the front, sharp detail, no folds, no seams, no text.` };
  return null;
}

// ---- item icons + posters (names come from the game page itself, so only real items can be drawn) ----
let ITEM_NAMES = null;
function itemName(id) { if (!ITEM_NAMES) { ITEM_NAMES = {}; for (const m of HTML.matchAll(/\{ id: '([a-z0-9_]+)', name: '([^']+)'/g)) if (!ITEM_NAMES[m[1]]) ITEM_NAMES[m[1]] = m[2]; } return ITEM_NAMES[id]; }
const ICON_STYLE = 'Video game shop item icon, single object centered, 3D render, glossy, soft studio lighting, rich colors, plain dark navy-to-purple gradient background with a soft neon glow behind the object, high detail. No text, no letters, no watermark.';
const ICON_CAT = {
  top: n => `a ${n} streetwear top for teens, folded product shot`, bottom: n => `${n} streetwear pants for teens, product shot`, shoes: n => `a pair of ${n} sneakers, product shot`,
  hat: n => `a ${n} hat, product shot`, gear: n => `${n} accessory item for an avatar`, hair: n => `a stylized ${n} hairstyle on a smooth faceless mannequin head`,
  blaster: n => `a futuristic toy laser tag blaster named ${n}, sleek sci-fi plastic and metal, glowing neon cyan and magenta accents`, ink: n => `a glowing ${n} laser beam energy effect, bright light streak`,
  pet: n => `a cute blocky voxel-style ${n} pet animal`, aura: n => `a magical ${n} glowing energy aura effect, sparkling light`, title: n => `a shiny golden achievement badge emblem representing "${n}"`,
  tune: n => `a glowing neon music note emblem with sound waves for a ${n} song`, wrap: n => `a futuristic blaster with a ${n} paint wrap finish`, food: n => `delicious ${n}, appetizing food photo`, drink: n => `a cold ${n} drink in a cup`,
  game: n => `${n} arcade game emblem`, mode: n => `${n} game mode emblem`,
};
const ICON_EXTRA = { game_dash: 'Neon Dash: a sleek neon race car', game_beat: 'Beat Drop: glowing rhythm game notes and headphones', game_smash: 'Target Smash: a red and white bullseye target', game_memory: 'Neon Memory: flipping glowing cards', game_hoops: 'Hoop Shot: basketball and hoop', mode_splat: 'Light Wars: two crossing laser beams, cyan versus magenta', mode_duel: 'Duel: two laser blasters facing off', mode_hill: 'Hill Hold: a glowing green capture zone circle with a flag on top of a small hill', mode_ffa: 'Free-for-All: a burst of many colorful laser beams crossing in all directions' };
function iconJob(key) {
  let m = key.match(/^icons\/([a-z]+)_([a-z0-9_]+)\.jpg$/); if (m && ICON_CAT[m[1]]) { const extra = ICON_EXTRA[m[1] + '_' + m[2]]; const n = extra || itemName(m[2]); if (!n || m[2] === 'none') return null;
    return { w: 512, h: 512, seed: 11, prompt: ICON_CAT[m[1]](n) + '. ' + ICON_STYLE }; }
  m = key.match(/^posters\/([a-z0-9-]{3,40})\.jpg$/); if (m) { const phrase = m[1].replace(/-/g, ' ').toUpperCase(); if (!HTML.includes("'" + phrase + "'") && !HTML.includes("'" + m[1].toUpperCase() + "'")) return null;
    return { w: 512, h: 768, seed: 5, prompt: `Vibrant vertical fashion magazine photo for a trendy teen mall store, themed around ${phrase.toLowerCase()}. Stylish product hero shot, colorful neon studio lighting, bold composition, clean empty background at the bottom. The image contains absolutely no words, no lettering, no captions, no logos, no watermark.` }; }
  return null;
}

const MG_BG = {
  dash: 'Top-down aerial view of a futuristic neon city at night seen from high above, glowing streets, rooftops with neon signs, cyan and magenta lights, synthwave mood',
  beat: 'A huge concert stage seen from the crowd at night, laser beams and spotlights in pink, cyan and gold, glowing LED walls, haze and confetti, energetic',
  smash: 'Inside a neon carnival shooting gallery booth, purple velvet backdrop, string lights, glowing arcade decorations, empty center area',
  hoops: 'Indoor basketball arena at night seen from courtside, glossy hardwood court, bright spotlights, blurred crowd and jumbotron glow',
  memory: 'Abstract dark neon background, soft glowing lime green and magenta bokeh lights, smooth gradient, futuristic and calm',
  claw: 'Looking through the glass of an arcade claw machine full of colorful cute plush toys, glowing pink neon trim, cozy arcade lights',
};
function mgJob(key) { const m = key.match(/^mg\/([a-z]+)\.jpg$/); if (!m || !MG_BG[m[1]]) return null; return { w: 768, h: 1024, seed: 21, prompt: MG_BG[m[1]] + '. Vertical mobile game background art, highly detailed, cinematic. No text, no letters, no logos, no watermark, no people in the foreground.' }; }
const AI_BUSY = new Map();
async function aiRun(env, model, inputs) {
  let out;
  if (model.includes('flux-2')) { const fd = new FormData(); for (const [k, v] of Object.entries(inputs)) fd.append(k, String(v)); const fr = new Response(fd); out = await env.AI.run(model, { multipart: { body: fr.body, contentType: fr.headers.get('content-type') } }); }
  else out = await env.AI.run(model, inputs);
  if (out instanceof ReadableStream) return new Uint8Array(await new Response(out).arrayBuffer());
  const b64 = out && (out.image || (out.images && out.images[0])); if (!b64) throw new Error('no image');
  return Uint8Array.from(atob(b64), c => c.charCodeAt(0));
}
async function aiArt(env, key, job) {
  if (AI_BUSY.has(key)) return AI_BUSY.get(key);
  const p = (async () => {
    let bytes, err = [];
    for (const [model, inp] of [['@cf/black-forest-labs/flux-2-dev', { prompt: job.prompt, width: job.w, height: job.h, seed: job.seed }], ['@cf/black-forest-labs/flux-1-schnell', { prompt: job.prompt, steps: 8 }]]) {
      try { bytes = await aiRun(env, model, inp); break; } catch (e) { err.push(model + ': ' + e.message); }
    }
    if (!bytes) throw new Error(err.join(' | '));
    await env.ART.put(key, bytes, { httpMetadata: { contentType: 'image/jpeg' } });
    return bytes;
  })();
  AI_BUSY.set(key, p); try { return await p; } finally { AI_BUSY.delete(key); }
}

export class GameRoom {
  constructor(state, env) { this.state = state; this.s = new Map(); this.n = 1; }
  host() { let h = null; for (const k of this.s.keys()) if (h === null || k < h) h = k; return h; }
  send(s, m) { try { s.ws.send(JSON.stringify(m)); } catch (e) { } }
  bcast(except, m) { const str = JSON.stringify(m); for (const s of this.s.values()) if (s !== except && s.ready) { try { s.ws.send(str); } catch (e) { } } }
  async fetch(req) {
    if (req.headers.get('Upgrade') !== 'websocket') return new Response('Expected websocket', { status: 426 });
    const pair = new WebSocketPair(); const [client, server] = Object.values(pair); server.accept();
    if (this.s.size >= 8) { server.send(JSON.stringify({ t: 'full' })); server.close(1000, 'full'); return new Response(null, { status: 101, webSocket: client }); }
    const id = this.n++; const sess = { id, ws: server, name: 'Player', look: null, ready: false, count: 0, win: Date.now() };
    this.s.set(id, sess);
    server.addEventListener('message', ev => {
      if (typeof ev.data !== 'string' || ev.data.length > 8000) return;
      const t = Date.now(); if (t - sess.win > 1000) { sess.win = t; sess.count = 0; } if (++sess.count > 120) return; // flood guard
      let m; try { m = JSON.parse(ev.data); } catch (e) { return; }
      if (!m || typeof m.t !== 'string') return;
      if (m.t === 'hello') {
        sess.name = String(m.name || 'Player').replace(/[^A-Za-z0-9 ]/g, '').slice(0, 24) || 'Player'; sess.look = m.look || null; sess.ready = true;
        const peers = [...this.s.values()].filter(x => x !== sess && x.ready).map(x => ({ id: x.id, name: x.name, look: x.look }));
        this.send(sess, { t: 'welcome', id, peers, host: this.host() });
        this.bcast(sess, { t: 'join', id, name: sess.name, look: sess.look });
        return;
      }
      if (!sess.ready) return;
      if (m.t === 'look') sess.look = m.look;
      m.from = id; this.bcast(sess, m);
    });
    const close = () => { if (!this.s.has(id)) return; this.s.delete(id); this.bcast(null, { t: 'leave', id, host: this.host() }); };
    server.addEventListener('close', close); server.addEventListener('error', close);
    return new Response(null, { status: 101, webSocket: client });
  }
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    if (url.pathname === '/ws') {
      if (!env.ROOMS) return new Response('Crew rooms not set up', { status: 501 });
      const code = (url.searchParams.get('room') || '').toUpperCase();
      if (!/^[A-Z0-9]{4,8}$/.test(code)) return new Response('Bad code', { status: 400 });
      return env.ROOMS.get(env.ROOMS.idFromName(code)).fetch(req);
    }
    if (url.pathname.startsWith('/art/')) {
      const key = decodeURIComponent(url.pathname.slice(5));
      if (!env.ART || !/^[A-Za-z0-9._/-]+$/.test(key) || key.includes('..')) return new Response('Not found', { status: 404 });
      const ext = key.split('.').pop().toLowerCase(), types = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', glb: 'model/gltf-binary', fbx: 'application/octet-stream', json: 'application/json', hdr: 'application/octet-stream' };
      let obj = await env.ART.get(key);
      const src = MODEL_SRC[key] || (key.startsWith('ubc/') ? GH2 + 'game/' + key.slice(4) : null);
      if (!obj && src) { // first request: copy the free KayKit (CC0) character files into R2, then serve from R2 forever
        const r = await fetch(src); if (!r.ok) return new Response('Not found', { status: 404 });
        const buf = await r.arrayBuffer(); const ct = types[ext] || 'application/octet-stream'; await env.ART.put(key, buf, { httpMetadata: { contentType: ct } });
        return new Response(buf, { headers: { 'content-type': ct, 'cache-control': key.endsWith('.json') ? 'no-cache' : 'public, max-age=86400' } });
      }
      if (!obj && env.AI) { const job = aiArtJob(key) || iconJob(key) || mgJob(key); if (job) { try { const bytes = await aiArt(env, key, job); return new Response(bytes, { headers: { 'content-type': 'image/jpeg', 'cache-control': 'public, max-age=3600' } }); } catch (e) { return new Response('Art not ready', { status: 503, headers: { 'x-gen-error': String(e.message).slice(0, 300) } }); } } }
      if (!obj) return new Response('Not found', { status: 404 });
      return new Response(obj.body, { headers: { 'content-type': (obj.httpMetadata && obj.httpMetadata.contentType) || types[ext] || 'application/octet-stream', 'cache-control': ext === 'json' ? 'no-cache' : 'public, max-age=3600' } });
    }
    if (url.pathname === '/health') return new Response('ok');
    return new Response(HTML, { headers: { 'content-type': 'text/html;charset=utf-8', 'cache-control': 'no-cache' } });
  }
};
